class LinkedList {
protected:
    Node* head;
    PcoMutex mutex;

public:
    LinkedList() : head(NULL)
    {
    }

    void push_front(int data)
    {
        // crée le nouveau noeud (allocation possible hors SC)
        Node *newNode = new Node(data);

        mutex.lock();
        // liste vide, assigne à head
        if (head == NULL) {
            head = newNode;
            mutex.unlock();
            return;
        }

        // insère le nouveau noeud
        newNode->next = this->head;
        this->head = newNode;
        mutex.unlock();
    }

    void pop_front()
    {
        mutex.lock();
        Node* temp = head;

        if (head == NULL) {
            // déjà vide
            mutex.unlock();
            return;
        }

        head = temp->next;
        mutex.unlock();
        delete temp; // libération possible après unlock
    }

    int get(unsigned int index, int* data)
    {
        mutex.lock();
        Node* next = head;
        unsigned int i = 0;

        // itère sur tous les noeuds
        while (next != NULL) {
            if (i == index) {
                *data = next->data;
                mutex.unlock();
                return 0;
            }
            next = next->next;
            i++;
        }
        mutex.unlock();
        return -1;
    }
};
```

