```cpp
class PontLevant
{
private:
    PcoSemaphore mutex;
    PcoSemaphore waitPont;
    bool estAbaisse;
    unsigned int nbWaiting;

public:
    PontLevant() : mutex(1), waitPont(0), estAbaisse(false), nbWaiting(0)
    {
    }

    ~PontLevant()
    {
    }

    void arrive()
    {
        mutex.acquire();
        if (!estAbaisse) {
            nbWaiting++;
            mutex.release();
            waitPont.acquire();
        } else {
            mutex.release();
        }
    }

    void abaisse()
    {
        mutex.acquire();
        estAbaisse = true;
        while (nbWaiting > 0) {
            nbWaiting--;
            waitPont.release();
        }
        mutex.release();
    }

    void releve()
    {
        mutex.acquire();
        estAbaisse = false;
        mutex.release();
    }
};
```

**Points clés de cette solution :**
* `abaisse()` est idempotent : si `estAbaisse` est déjà `true`, `nbWaiting` vaut `0`, donc la boucle `while` ne fait rien.
* `releve()` est idempotent : il met simplement `estAbaisse = false` sous `mutex`.
* Aucun `release()` superflu n'est accumulé dans `waitPont` !
